  border-radius: 9999rem;
}

.bds-atom-orbit {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: rotate(var(--bds-atom-tilt)) rotateX(90deg);
}

.bds-atom-ring {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  border: ${INNER_STROKE} solid currentColor;
