      <div {...spinnerRoot("atom", rest)}>
        <div className="bds-atom-shell" />
        {ORBITS.map((index) => (
          <div
            className="bds-atom-orbit"
            key={index}
            style={cssVars({ "--bds-atom-tilt": `${index * TILT}deg` })}
          >
            <div className={spinClass("atom", easing)} style={step(index)}>
              <div className="bds-atom-ring" />
            </div>
          </div>
        ))}
      </div>
    </>
  );
}

